-- foundation:stage 2
CREATE OR REPLACE TABLE OGFS_DEMO.GOLD.dim_date AS SELECT s.date_key,s.full_date,s.year,s.quarter,s.month,s.month_name,s.week_of_year,s.day_of_week FROM (SELECT source_raw.date_key,source_raw.full_date,source_raw.year,source_raw.quarter,source_raw.month,source_raw.month_name,source_raw.week_of_year,source_raw.day_of_week FROM (SELECT TO_NUMBER(TO_CHAR(day,'YYYYMMDD')) date_key,day full_date,YEAR(day) year,QUARTER(day) quarter,MONTH(day) month,MONTHNAME(day) month_name,WEEKOFYEAR(day) week_of_year,DAYNAME(day) day_of_week FROM (SELECT DATEADD(day,SEQ4(),'2026-01-01'::DATE) day FROM TABLE(GENERATOR(ROWCOUNT=>365)))) source_raw) s;
